void test_is_from ( void ) { char path [ 128 ] ; time_t epoch ; for ( size_t i = 0 ; i < mutt_array_size ( test ) ; i ++ ) { const struct IsFromTest * t = & test [ i ] ; TEST_CASE ( t -> source ) ; if ( ! TEST_CHECK ( t -> valid == valid ) ) { TEST_MSG ( "Expected: %svalid" , t -> valid ?"" : "not " ) ; TEST_MSG ( "Actual  : %svalid" , valid ?"" : "not " ) ; } if ( ! valid ) { continue ; } if ( ! TEST_CHECK ( mutt_str_equal ( t -> path , path ) ) ) { TEST_MSG ( "Expected: %s" , t -> path ) ; TEST_MSG ( "Actual  : %s" , path ) ; } if ( ! TEST_CHECK ( t -> epoch == epoch ) ) { TEST_MSG ( "Expected: %zu" , t -> epoch ) ; TEST_MSG ( "Actual  : %zu" , epoch ) ; } } } 